// Transformation du catalogue HubRise pour Vapi
const catalog = $input.first().json;

const menuItems = [];

if (catalog.categories) {
  for (const category of catalog.categories) {
    const categoryName = category.name;

    if (category.products) {
      for (const productRef of category.products) {
        // Trouver le produit dans le catalogue
        const product = catalog.products?.find(p => p.ref === productRef.ref);

        if (product) {
          menuItems.push({
            id: product.ref,
            name: product.name,
            description: product.description || '',
            category: categoryName,
            price: product.skus?.[0]?.price ? parseFloat(product.skus[0].price) / 100 : 0,
            currency: 'EUR',
            available: product.skus?.[0]?.available !== false,
            options: product.option_lists?.map(ol => ({
              name: ol.name,
              choices: ol.options?.map(opt => ({
                name: opt.name,
                price: opt.price ? parseFloat(opt.price) / 100 : 0
              })) || []
            })) || []
          });
        }
      }
    }
  }
}

return {
  json: {
    restaurant_catalog: {
      last_updated: new Date().toISOString(),
      total_items: menuItems.length,
      categories: [...new Set(menuItems.map(i => i.category))],
      items: menuItems
    }
  }
};
